1	import { trace, SpanKind, Span } from "@opentelemetry/api";
2	import { createShapeId } from "@tldraw/tlschema";
3	import { getOrCreateRoom, RoomEntry, PlayerArea } from "./rooms.js";
4	import { slugifyTableName, tableNameFromSlug } from "../shared/slugify.js";
5	import { CARD_W, CARD_H, MAX_SEATS, graveyardCardPosition, stackCardPosition } from "./cardLayout.js";
6	import { pageIdOf, nextIndex, mtgCardShape } from "./tableFurniture.js";
7	import { validateIncomingEvent } from "./contractValidation.js";
8	
9	const tracer = trace.getTracer("mtg-tabletop");
10	
11	
12	type ZoneHint = "stack" | "battlefield";
13	
14	/** Sibling of card.played — identical payload shape, but means "mint this concealed." */
15	const FACE_DOWN_EVENT_NAME = "card.played-face-down";
16	const DISCARD_EVENT_NAME = "card.discarded";
17	
18	function isFaceDownEnvelope(body: unknown): boolean {
19	  return typeof body === "object" && body !== null && "name" in body && (body as { name: unknown }).name === FACE_DOWN_EVENT_NAME;
20	}
21	
22	interface CardArrivalPayloadCommon {
23	  card: { scryfallId: string; instanceId: string };
24	  face: "front" | "back";
25	  frontImageUrl: string;
26	  backImageUrl: string | null;
27	  cardName: string;
28	  owner: string;
29	  isCommander: boolean;
30	  gameCardIndex?: number;
31	}
32	
33	interface CardPlayedPayload extends CardArrivalPayloadCommon {
34	  zoneHint: ZoneHint;
35	}
36	
37	type CardDiscardedPayload = CardArrivalPayloadCommon;
38	
39	export type CardArrivalOutcome =
40	  | { status: "invalid"; error: string }
41	  | { status: "placed" }
42	  | { status: "deduped"; reason: "event-id" | "instance" }
43	  | { status: "rejected"; reason: "table-full" | "seat-not-joined" };
44	
45	/**
46	 * The shared core of "a card arrives on the table" — validation-independent: dedup, seat
47	 * checks, and shape placement. Both card.played/-face-down (positioned via zoneHint) and
48	 * card.discarded (always the graveyard) funnel through here once they've resolved a
49	 * position, so dedup/placement never drifts between the two event kinds.
50	 */
51	async function placeArrivedCard(
52	  tableName: string,
53	  envelope: { id: string; name: string; initiator: { seatId?: string } },
54	  payload: CardArrivalPayloadCommon,
55	  faceDown: boolean,
56	  resolvePosition: (entry: RoomEntry, playerArea: PlayerArea, span: Span) => { x: number; y: number }
57	): Promise<CardArrivalOutcome> {
58	  const seatId = envelope.initiator.seatId;
59	  if (!seatId) {
60	    return { status: "invalid", error: `initiator.seatId is required for ${envelope.name}` };
61	  }
62	  const { card, face, frontImageUrl, backImageUrl, cardName, owner, isCommander, gameCardIndex } = payload;
63	
64	  trace.getActiveSpan()?.setAttributes({
65	    "card.instance_id": card.instanceId,
66	    "card.scryfall_id": card.scryfallId,
67	    "card.name": cardName,
68	    "event.id": envelope.id,
69	    "event.name": envelope.name,
70	    "table.name": tableNameFromSlug(tableName),
71	    "table.slug": tableName,
72	    "seat.id": seatId,
73	  });
74	
75	  const entry = getOrCreateRoom(tableName);
76	
77	  // Dedup 1: a retried request (same event id — worked but failed to ack).
78	  if (entry.seenEventIds.has(envelope.id)) {
79	    trace.getActiveSpan()?.setAttribute("arrival.deduped", "event-id");
80	    return { status: "deduped", reason: "event-id" };
81	  }
82	  if (entry.hasInstance(card.instanceId)) {
83	    entry.seenEventIds.add(envelope.id);
84	    trace.getActiveSpan()?.setAttribute("arrival.deduped", "instance");
85	    return { status: "deduped", reason: "instance" };
86	  }
87	
88	  if (!entry.seats.has(owner) && entry.seats.size >= MAX_SEATS) {
89	    trace.getActiveSpan()?.setAttribute("arrival.rejected", "table-full");
90	    return { status: "rejected", reason: "table-full" };
91	  }
92	
93	  const playerArea = entry.seats.get(owner);
94	  if (!playerArea) {
95	    // A card arrival for a seat with no player area means seat.joined hasn't landed yet —
96	    // an ordering bug upstream, not something to paper over by minting furniture from
97	    // whatever scraps this payload happens to carry (no deck name, no sleeve, no playmat).
98	    trace.getActiveSpan()?.setAttribute("arrival.rejected", "seat-not-joined");
99	    return { status: "rejected", reason: "seat-not-joined" };
100	  }
101	
102	  const pageId = pageIdOf(entry);
103	
104	  await tracer.startActiveSpan(
105	    "place arrived card",
106	    {
107	      kind: SpanKind.INTERNAL,
108	      attributes: {
109	        "event.id": envelope.id,
110	        "event.name": envelope.name,
111	        "table.name": tableNameFromSlug(tableName),
112	        "table.slug": tableName,
113	        "seat.id": seatId,
114	        "card.instance_id": card.instanceId,
115	        "card.scryfall_id": card.scryfallId,
116	        "card.name": cardName,
117	      },
118	    },
119	    async (span) => {
120	      try {
121	        const position = resolvePosition(entry, playerArea, span);
122	
123	        const shapeId = createShapeId(`card-${card.instanceId}`);
124	
125	        await entry.room.updateStore((store) => {
126	          store.put(
127	            mtgCardShape({
128	              id: shapeId,
129	              pageId,
130	              x: position.x,
131	              y: position.y,
132	              w: CARD_W,
133	              h: CARD_H,
134	              index: nextIndex(tableName),
135	              instanceId: card.instanceId,
136	              scryfallId: card.scryfallId,
137	              cardName: cardName,
138	              frontImageUrl: frontImageUrl,
139	              backImageUrl: backImageUrl,
140	              face: face,
141	              faceDown,
142	              sleeveColor: playerArea.sleeveColor ?? null,
143	              cardBackImageUrl: playerArea.cardBackImageUrl ?? null,
144	              owner,
145	              isCommander,
146	              gameCardIndex: gameCardIndex ?? null,
147	            })
148	          );
149	        });
150	
151	        span.setAttribute("zone.position.x", position.x);
152	        span.setAttribute("zone.position.y", position.y);
153	      } finally {
154	        span.end();
155	      }
156	    }
157	  );
158	
159	  entry.seenEventIds.add(envelope.id);
160	  return { status: "placed" };
161	}
162	
163	/**
164	 * card.played / card.played-face-down: validation, dedup, and placement onto the stack or
165	 * battlefield per zoneHint. The only production entry point is the Spine SSE dispatcher
166	 * (`spineEventDispatch.ts`); `testSeedRoute.ts` calls this directly too, as a test-only HTTP
167	 * seam for specs that need to seed a card without a live Spine.
168	 */
169	export async function applyCardArrival(tableName: string, body: unknown): Promise<CardArrivalOutcome> {
170	  const faceDown = isFaceDownEnvelope(body);
171	  const result = validateIncomingEvent<CardPlayedPayload>(body, faceDown ? FACE_DOWN_EVENT_NAME : "card.played");
172	  if (!result.ok) {
173	    return { status: "invalid", error: result.error };
174	  }
175	  const { envelope } = result;
176	  if (slugifyTableName(envelope.tableId) !== tableName) {
177	    return { status: "invalid", error: "envelope tableId does not match the table being posted to" };
178	  }
179	
180	  const { zoneHint } = envelope.payload;
181	  trace.getActiveSpan()?.setAttribute("zone.hint", zoneHint);
182	
183	  return placeArrivedCard(tableName, envelope, envelope.payload, faceDown, (entry, playerArea, span) => {
184	    // battlefield (a land) arrives on the Stack with everything else; a human drags it to
185	    // the playmat. stack/battlefield both land here — zoneHint is otherwise unused now.
186	    const stackCount = entry.stackCardCount(envelope.payload.owner);
187	    span.setAttribute("zone.stack_count", stackCount);
188	    return stackCardPosition(playerArea.seatIndex, stackCount);
189	  });
190	}
191	
192	/**
193	 * card.discarded: validation, dedup, and placement onto the graveyard cascade. Discard
194	 * traffic (discard-from-hand, mill) has its own event kind rather than a card.played with
195	 * a graveyard zoneHint (tabletop-cards-come-and-go ticket 08) — routed here by event kind,
196	 * not by a zone hint the payload no longer carries.
197	 */
198	export async function applyCardDiscard(tableName: string, body: unknown): Promise<CardArrivalOutcome> {
199	  const result = validateIncomingEvent<CardDiscardedPayload>(body, DISCARD_EVENT_NAME);
200	  if (!result.ok) {
201	    return { status: "invalid", error: result.error };
202	  }
203	  const { envelope } = result;
204	  if (slugifyTableName(envelope.tableId) !== tableName) {
205	    return { status: "invalid", error: "envelope tableId does not match the table being posted to" };
206	  }
207	
208	  return placeArrivedCard(tableName, envelope, envelope.payload, false, (_entry, playerArea, span) => {
209	    const position = graveyardCardPosition(playerArea.seatIndex, playerArea.graveyardCount++);
210	    span.setAttribute("zone.graveyard_count", playerArea.graveyardCount);
211	    return position;
212	  });
213	}
