1	import { context, propagation, ROOT_CONTEXT, trace, SpanKind } from "@opentelemetry/api";
2	import { applyCardArrival, applyCardDiscard } from "./cardArrival.js";
3	import { applyCardRemoval } from "./cardRemoval.js";
4	import { tableNameFromSlug } from "../shared/slugify.js";
5	import { log } from "./log.js";
6	
7	const tracer = trace.getTracer("mtg-tabletop");
8	
9	function isEnvelopeLike(value: unknown): value is { name: string; traceparent?: unknown } {
10	  return typeof value === "object" && value !== null && "name" in value && typeof (value as { name: unknown }).name === "string";
11	}
12	
13	/**
14	 * Dispatches one event received over a Spine SSE subscription by `name`. Every kind gets
15	 * a span carrying `event.name` — matching the Spine admin page's precedent for the same
16	 * attribute — so all events are graphable by name in Honeycomb, even kinds with no
17	 * consumer yet (only `card.played` is routed to `applyCardArrival` today). Continues the
18	 * trace from the broadcast envelope's `traceparent` (injected fresh at publish time by the
19	 * Spine's `Table#broadcast`) as a CHILD span, the same shape as the admin page's
20	 * client-side trace-link precedent — the point is one Honeycomb trace covering publish
21	 * through Tabletop placement, not an unlinked new one.
22	 */
23	const CARD_ARRIVAL_EVENT_NAMES = new Set(["card.played", "card.played-face-down"]);
24	const CARD_DISCARD_EVENT_NAMES = new Set(["card.discarded"]);
25	const CARD_REMOVAL_EVENT_NAMES = new Set(["card.returned"]);
26	
27	export function dispatchSpineEvent(tableName: string, event: unknown): void {
28	  if (!isEnvelopeLike(event)) return;
29	
30	  const traceparent = typeof event.traceparent === "string" ? event.traceparent : undefined;
31	  const parentContext = traceparent ? propagation.extract(ROOT_CONTEXT, { traceparent }) : ROOT_CONTEXT;
32	
33	  context.with(parentContext, () => {
34	    void tracer.startActiveSpan(
35	      `sse subscription: ${event.name}`,
36	      {
37	        kind: SpanKind.CONSUMER,
38	        attributes: {
39	          "event.name": event.name,
40	          "table.name": tableNameFromSlug(tableName),
41	          "table.slug": tableName,
42	        },
43	      },
44	      async (span) => {
45	        try {
46	          if (CARD_ARRIVAL_EVENT_NAMES.has(event.name)) {
47	            const outcome = await applyCardArrival(tableName, event);
48	            span.setAttribute("arrival.outcome", outcome.status);
49	            if (outcome.status === "invalid") {
50	              log.warn(`spine sse: ${event.name} event failed validation`, {
51	                "table.slug": tableName,
52	                "arrival.error": outcome.error,
53	              });
54	            }
55	            if (outcome.status === "rejected" && outcome.reason === "seat-not-joined") {
56	              span.setAttribute("error", true);
57	              log.error(`spine sse: ${event.name} arrived before seat.joined — dropping, not fabricating furniture`, {
58	                "table.slug": tableName,
59	                error: true,
60	              });
61	            }
62	            return;
63	          }
64	
65	          if (CARD_DISCARD_EVENT_NAMES.has(event.name)) {
66	            const outcome = await applyCardDiscard(tableName, event);
67	            span.setAttribute("arrival.outcome", outcome.status);
68	            if (outcome.status === "invalid") {
69	              log.warn(`spine sse: ${event.name} event failed validation`, {
70	                "table.slug": tableName,
71	                "arrival.error": outcome.error,
72	              });
73	            }
74	            if (outcome.status === "rejected" && outcome.reason === "seat-not-joined") {
75	              span.setAttribute("error", true);
76	              log.error(`spine sse: ${event.name} arrived before seat.joined — dropping, not fabricating furniture`, {
77	                "table.slug": tableName,
78	                error: true,
79	              });
80	            }
81	            return;
82	          }
83	
84	          if (CARD_REMOVAL_EVENT_NAMES.has(event.name)) {
85	            const outcome = await applyCardRemoval(tableName, event);
86	            span.setAttribute("removal.outcome", outcome.status);
87	            if (outcome.status === "invalid") {
88	              log.warn(`spine sse: ${event.name} event failed validation`, {
89	                "table.slug": tableName,
90	                "removal.error": outcome.error,
91	              });
92	            }
93	            return;
94	          }
95	        } catch (error) {
96	          span.recordException(error as Error);
97	          log.error(`spine sse: ${event.name} dispatch failed`, { "table.slug": tableName }, error);
98	        } finally {
99	          span.end();
100	        }
101	      }
102	    );
103	  });
104	}
